-- Synthetic column-only schema for checkout/canteen contracts. No production data.
-- Other financial, permission and hold trigger suites cover their own boundaries.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role; CREATE SCHEMA auth; CREATE SCHEMA private;
CREATE TYPE public.user_role AS ENUM ('super_admin','lounge_owner','manager','cashier','customer','lounge_admin');
CREATE TYPE public.kyc_status AS ENUM ('pending','approved','rejected');
CREATE TYPE public.staff_role AS ENUM ('lounge_owner','manager','cashier');
CREATE TYPE public.shift_status AS ENUM ('open','closed');
CREATE TYPE public.booking_status AS ENUM ('upcoming','completed','cancelled','pending','in_progress','rejected','expired');
CREATE TYPE public.payment_method AS ENUM ('card','vodafone_cash','instapay','fawry','cash','app_wallet');
CREATE TYPE public.payment_status AS ENUM ('unpaid','paid','refunded','partially_paid');
CREATE TYPE public.announcement_type AS ENUM ('info','warning','update');
CREATE TYPE public.user_ban_request_status AS ENUM ('pending','approved_lounge_only','approved_global','rejected');
CREATE TYPE public.announcement_target_audience AS ENUM ('all','owners','specific_venue');
CREATE TABLE public.rooms (id uuid DEFAULT gen_random_uuid() NOT NULL,lounge_id uuid,name text NOT NULL,photo_url text,images text[],features text[],is_available boolean DEFAULT true,controllers_count integer DEFAULT 2,screen_size text DEFAULT '43"'::text,status text DEFAULT 'available'::text,created_at timestamp with time zone DEFAULT now(),name_ar text,name_en text,features_ar text[],features_en text[],description_ar text,description_en text,extra_controller_price numeric DEFAULT 0,device_type text,room_type text DEFAULT 'standard'::text,hourly_rate_single numeric DEFAULT 0,hourly_rate_multi numeric DEFAULT 0,max_capacity integer DEFAULT 4,description text,is_active boolean DEFAULT true,updated_at timestamp with time zone DEFAULT now(),hourly_rate numeric,space_type_id uuid,control_type text DEFAULT 'manual'::text NOT NULL,relay_channel integer,relay_ip character varying,relay_mac character varying,open_time_enabled boolean DEFAULT true NOT NULL,open_time_pricing_mode text DEFAULT 'same_hourly'::text NOT NULL,open_time_custom_hourly_rate numeric(10,2),open_time_price_multiplier numeric(8,4) DEFAULT 1.0 NOT NULL,open_time_minimum_minutes integer DEFAULT 30 NOT NULL,open_time_rounding_minutes integer DEFAULT 15 NOT NULL,open_time_max_minutes integer DEFAULT 720,open_time_buffer_before_booking_minutes integer DEFAULT 15 NOT NULL,resource_type text DEFAULT 'console'::text,resource_attributes jsonb DEFAULT '{}'::jsonb,requires_screen boolean DEFAULT true,requires_controllers boolean DEFAULT true,pricing_model text DEFAULT 'per_room_hour'::text,min_capacity integer DEFAULT 1);
ALTER TABLE public.rooms ADD PRIMARY KEY(id);
CREATE TABLE public.extras (id uuid DEFAULT gen_random_uuid() NOT NULL,lounge_id uuid,name text NOT NULL,price numeric NOT NULL,category text NOT NULL,icon text,is_available boolean DEFAULT true,created_at timestamp without time zone DEFAULT now(),name_ar text,name_en text,is_active boolean DEFAULT true,stock_quantity integer DEFAULT 0,track_stock boolean DEFAULT true,min_stock_alert integer DEFAULT 5,icon_key text DEFAULT 'fastfood'::text,image_url text,cost_price numeric);
ALTER TABLE public.extras ADD PRIMARY KEY(id);
CREATE TABLE public.shifts (id uuid DEFAULT gen_random_uuid() NOT NULL,lounge_id uuid NOT NULL,staff_user_id uuid,opened_at timestamp with time zone DEFAULT now() NOT NULL,closed_at timestamp with time zone,status text DEFAULT 'open'::text NOT NULL,starting_cash numeric DEFAULT 0 NOT NULL,expected_cash numeric DEFAULT 0,actual_cash_counted numeric,notes text,created_at timestamp with time zone DEFAULT now(),cashier_id uuid,start_time timestamp with time zone DEFAULT now(),end_time timestamp with time zone,difference numeric(10,2) DEFAULT 0.00,total_cash_sales numeric(10,2) DEFAULT 0.00,total_digital_sales numeric(10,2) DEFAULT 0.00,total_expenses numeric(10,2) DEFAULT 0.00,payment_method text DEFAULT 'cash'::text,is_approved boolean DEFAULT false,approved_by uuid,approved_at timestamp with time zone,manager_notes text);
ALTER TABLE public.shifts ADD PRIMARY KEY(id);
CREATE TABLE public.lounges (id uuid DEFAULT gen_random_uuid() NOT NULL,owner_id uuid,name text NOT NULL,image_url text,images text[],location text,city text DEFAULT 'Cairo'::text,maps_link text,rating numeric DEFAULT 0,total_reviews integer DEFAULT 0,available_rooms integer DEFAULT 0,is_open boolean DEFAULT true,status text DEFAULT 'pending'::text,created_at timestamp with time zone DEFAULT now(),description_ar text,description_en text,address text,contact_phone text,opening_time time without time zone,closing_time time without time zone,is_active boolean DEFAULT true,has_discount boolean DEFAULT false,discount_percentage integer DEFAULT 0,discount_title_ar text,discount_title_en text,discount_expires_at timestamp with time zone,name_ar text,name_en text,city_id uuid,vodafone_cash_number text,instapay_account text,allow_cash_payment boolean DEFAULT true NOT NULL,require_prepaid_first_time boolean DEFAULT true NOT NULL,cash_grace_period_minutes integer DEFAULT 10 NOT NULL,wallet_number text,instapay_handle text,suspension_reason text,brand_id uuid,branch_name character varying(255),is_main_branch boolean DEFAULT false NOT NULL,parent_lounge_id uuid,allow_open_time_sessions boolean DEFAULT false NOT NULL,open_time_rounding_minutes integer DEFAULT 15 NOT NULL,open_time_minimum_minutes integer DEFAULT 60 NOT NULL,open_time_max_minutes integer DEFAULT 720 NOT NULL,timezone text DEFAULT 'Africa/Cairo'::text NOT NULL,allow_future_bookings boolean DEFAULT true NOT NULL,allow_request_without_shift boolean DEFAULT true NOT NULL,future_booking_max_days_advance integer DEFAULT 14 NOT NULL,unconfirmed_alert_lead_minutes integer DEFAULT 60 NOT NULL,require_deposit_for_future boolean DEFAULT false NOT NULL,future_deposit_percentage integer DEFAULT 20 NOT NULL);
ALTER TABLE public.lounges ADD PRIMARY KEY(id);
CREATE TABLE public.bookings (id uuid DEFAULT gen_random_uuid() NOT NULL,user_id uuid,room_id uuid,lounge_id uuid,date date NOT NULL,start_time time without time zone NOT NULL,end_time time without time zone NOT NULL,room_price numeric(12,2) NOT NULL,addons_price numeric(12,2) DEFAULT 0,total_price numeric(12,2) NOT NULL,status booking_status DEFAULT 'pending'::booking_status,qr_code text,created_at timestamp with time zone DEFAULT now(),user_name text,user_phone text,room_name text,booking_period tsrange GENERATED ALWAYS AS (tsrange(date+start_time,date+end_time+CASE WHEN end_time<=start_time THEN interval '1 day' ELSE interval '0' END,'[)')) STORED,duration_hours numeric,play_mode text,extra_controllers integer DEFAULT 0,payment_status text DEFAULT 'unpaid'::text,shift_id uuid,duration_minutes integer DEFAULT 60,payment_method text DEFAULT 'cash'::text NOT NULL,discount_amount numeric(12,2) DEFAULT 0,discount_percentage numeric DEFAULT 0,discount_reason text,discount_approved_by uuid,actual_start_time timestamp with time zone,updated_at timestamp with time zone DEFAULT now(),extension_status text DEFAULT 'none'::text,requested_extension_minutes integer DEFAULT 0,start_at time without time zone,end_at time without time zone,receipt_url text,expires_at timestamp with time zone DEFAULT (now() + '00:30:00'::interval),sender_wallet_phone text,is_first_booking boolean DEFAULT false NOT NULL,checked_in_at timestamp with time zone,cancellation_reason text,addons_total numeric DEFAULT 0,approved_at timestamp with time zone,approved_by uuid,cancelled_at timestamp with time zone,cancelled_by uuid,is_open_time boolean DEFAULT false NOT NULL,open_time_started_at timestamp with time zone,open_time_closed_at timestamp with time zone,open_time_billing_minutes integer,open_time_pricing_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,confirmation_status text DEFAULT 'confirmed'::text NOT NULL,deposit_required boolean DEFAULT false NOT NULL,deposit_amount numeric DEFAULT 0 NOT NULL,deposit_paid boolean DEFAULT false NOT NULL,confirmation_sent_at timestamp with time zone,contact_alert_sent_at timestamp with time zone,cashier_closed_at timestamp with time zone,cashier_booking_timezone text,cashier_capacity_period tsrange,applied_voucher_code text);
ALTER TABLE public.bookings ADD PRIMARY KEY(id);
CREATE TABLE public.profiles (id uuid NOT NULL,lounge_id uuid,role text DEFAULT 'cashier'::text NOT NULL,full_name text,phone text,email text,is_active boolean DEFAULT true,created_at timestamp with time zone DEFAULT now(),updated_at timestamp with time zone DEFAULT now(),avatar_url text,is_setup_completed boolean DEFAULT true,fcm_token text,referral_code text,referred_by uuid,points integer DEFAULT 0,is_banned boolean DEFAULT false,city_id uuid,latitude double precision,longitude double precision,completed_bookings_count integer DEFAULT 0 NOT NULL,banned_reason text,notification_preferences jsonb DEFAULT '{"push_notifications_enabled": true}'::jsonb);
ALTER TABLE public.profiles ADD PRIMARY KEY(id);
CREATE TABLE public.promotions (id uuid DEFAULT gen_random_uuid() NOT NULL,title text NOT NULL,tag text,colors text[] DEFAULT '{}'::text[] NOT NULL,icon_key text,image_url text,deep_link text,is_active boolean DEFAULT true NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,title_ar text,title_en text,tag_ar text,tag_en text,lounge_id uuid,expires_at timestamp with time zone,is_room_specific boolean DEFAULT false,room_id uuid,target_audience text DEFAULT 'local'::text,discount_type text DEFAULT 'percentage'::text,discount_value numeric DEFAULT 0,archived_at timestamp with time zone,archived_by uuid,reshared_from_id uuid);
ALTER TABLE public.promotions ADD PRIMARY KEY(id);
CREATE TABLE public.upsell_rules (id uuid DEFAULT gen_random_uuid() NOT NULL,lounge_id uuid NOT NULL,trigger_type text NOT NULL,trigger_params jsonb DEFAULT '{}'::jsonb NOT NULL,suggest_extra_id uuid,suggest_combo_id uuid,discount_percent numeric,max_impressions_per_booking integer DEFAULT 2 NOT NULL,priority integer DEFAULT 100 NOT NULL,is_active boolean DEFAULT true NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.upsell_rules ADD PRIMARY KEY(id);
CREATE TABLE public.booking_holds (id uuid DEFAULT gen_random_uuid() NOT NULL,hold_token uuid NOT NULL,user_id uuid NOT NULL,lounge_id uuid NOT NULL,room_id uuid NOT NULL,start_at timestamp without time zone NOT NULL,end_at timestamp without time zone NOT NULL,expires_at timestamp with time zone NOT NULL,released_at timestamp with time zone,created_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.booking_holds ADD PRIMARY KEY(id);
CREATE TABLE public.booking_items (id uuid DEFAULT gen_random_uuid() NOT NULL,booking_id uuid,product_id uuid,quantity integer NOT NULL,unit_price numeric NOT NULL,total_price numeric NOT NULL,name text,note text,price numeric DEFAULT 0.0,created_at timestamp with time zone DEFAULT now() NOT NULL,status text DEFAULT 'pending'::text,item_id text,extra_id uuid,is_attended boolean DEFAULT false NOT NULL,is_read boolean DEFAULT false NOT NULL);
ALTER TABLE public.booking_items ADD PRIMARY KEY(id);
CREATE TABLE public.pricing_rules (id uuid DEFAULT gen_random_uuid() NOT NULL,lounge_id uuid NOT NULL,space_type_id uuid,room_id uuid,name_ar text NOT NULL,name_en text NOT NULL,rule_type text DEFAULT 'peak'::text NOT NULL,days_of_week integer[] DEFAULT ARRAY[1, 2, 3, 4, 5, 6, 7] NOT NULL,start_time time without time zone NOT NULL,end_time time without time zone NOT NULL,start_date date,end_date date,adjustment_type text DEFAULT 'multiplier'::text NOT NULL,adjustment_value numeric NOT NULL,is_active boolean DEFAULT true NOT NULL,priority integer DEFAULT 10 NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.pricing_rules ADD PRIMARY KEY(id);
CREATE TABLE public.user_vouchers (id uuid DEFAULT gen_random_uuid() NOT NULL,user_id uuid NOT NULL,redemption_option_id uuid,code text NOT NULL,reward_type text NOT NULL,reward_value numeric,status text DEFAULT 'active'::text NOT NULL,expires_at timestamp with time zone NOT NULL,used_at timestamp with time zone,used_booking_id uuid,created_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.user_vouchers ADD PRIMARY KEY(id);
CREATE TABLE public.canteen_combos (id uuid DEFAULT gen_random_uuid() NOT NULL,lounge_id uuid NOT NULL,name_ar text NOT NULL,name_en text,description_ar text,description_en text,image_url text,price numeric NOT NULL,days_of_week integer[],available_from time without time zone,available_to time without time zone,valid_from date,valid_to date,is_active boolean DEFAULT true NOT NULL,sort_order integer DEFAULT 0 NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,updated_at timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public.canteen_combos ADD PRIMARY KEY(id);
CREATE TABLE public.canteen_orders (id uuid DEFAULT gen_random_uuid() NOT NULL,booking_id uuid,lounge_id uuid,user_id uuid,items jsonb,total_price numeric(10,2) NOT NULL,note text,status text DEFAULT 'pending'::text,created_at timestamp with time zone DEFAULT now(),is_attended boolean DEFAULT false NOT NULL,is_read boolean DEFAULT false NOT NULL,notes text,updated_at timestamp with time zone DEFAULT now(),shift_id uuid);
ALTER TABLE public.canteen_orders ADD PRIMARY KEY(id);
CREATE TABLE public.shift_payments (id uuid DEFAULT gen_random_uuid() NOT NULL,shift_id uuid NOT NULL,lounge_id uuid NOT NULL,booking_id uuid,payment_method text NOT NULL,category text NOT NULL,amount numeric NOT NULL,paid_at timestamp with time zone DEFAULT now(),created_at timestamp with time zone DEFAULT now(),canteen_order_id uuid);
ALTER TABLE public.shift_payments ADD PRIMARY KEY(id);
CREATE TABLE public.canteen_combo_items (combo_id uuid NOT NULL,extra_id uuid NOT NULL,quantity integer DEFAULT 1 NOT NULL);
ALTER TABLE public.canteen_combo_items ADD PRIMARY KEY(combo_id,extra_id);
CREATE TABLE public.canteen_order_items (id uuid DEFAULT gen_random_uuid() NOT NULL,order_id uuid,extra_id uuid,quantity integer NOT NULL,unit_price numeric(12,2) NOT NULL,total_price numeric(12,2) NOT NULL,created_at timestamp with time zone DEFAULT now(),item_name text);
ALTER TABLE public.canteen_order_items ADD PRIMARY KEY(id);
CREATE TABLE public.canteen_upsell_events (id uuid DEFAULT gen_random_uuid() NOT NULL,lounge_id uuid NOT NULL,rule_id uuid,booking_id uuid,event_type text NOT NULL,revenue_generated numeric DEFAULT 0 NOT NULL,created_at timestamp with time zone DEFAULT now() NOT NULL,canteen_order_id uuid);
ALTER TABLE public.canteen_upsell_events ADD PRIMARY KEY(id);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT NULLIF(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION public.is_super_admin() RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION public._playspot_has_lounge_access(uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE FUNCTION private.can_operate_playspot_lounge(uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
